/* Reference presets keep actual geometry, occupancy and equipment editable. */
(function(){'use strict';
const pressure=z=>101.325*Math.pow(1-2.25577e-5*z,5.2559),round=(n,d)=>+n.toFixed(d);
const U=(film,layers)=>round(1/(film+layers.reduce((r,[d,k])=>r+d/k,0)),2);
const data={
 city:[['hanoi','Hà Nội','Hanoi',35.1,27.4,12],['danang','Đà Nẵng','Da Nang',35.7,26.3,10],['hcm','TP.HCM','Ho Chi Minh City',34.9,25.7,10],['haiphong','Hải Phòng','Hai Phong',33.3,28.7,116]],
 use:[['office','Văn phòng · làm việc nhẹ','Office · light activity',{persons:73,personl:59,lights:8}],['restaurant','Nhà hàng · khu ăn uống','Restaurant · dining area',{persons:81,personl:81,lights:10}],['factory','Nhà máy · thao tác nhẹ','Factory · light bench work',{persons:81,personl:139,lights:10}],['gym','Gym · vận động mạnh','Gym · vigorous exercise',{persons:208,personl:320,lights:8}]],
 wall:[['brick110','Gạch đặc 110 mm + trát hai mặt','110 mm solid brick + plaster both sides',{uwall:U(.17,[[.11,.77],[.03,.72]])}],['brick220','Gạch đặc 220 mm + trát hai mặt','220 mm solid brick + plaster both sides',{uwall:U(.17,[[.22,.77],[.03,.72]])}],['brick-ins','Gạch đặc 110 mm + trát + cách nhiệt 50 mm','110 mm solid brick + plaster + 50 mm insulation',{uwall:U(.17,[[.11,.77],[.03,.72],[.05,.035]])}]],
 roof:[['concrete','Bê tông 150 mm + trát 15 mm','150 mm concrete + 15 mm plaster',{uroof:U(.14,[[.15,2.5],[.015,.72]])}],['concrete-ins','Bê tông 150 mm + trát + cách nhiệt 50 mm','150 mm concrete + plaster + 50 mm insulation',{uroof:U(.14,[[.15,2.5],[.015,.72],[.05,.035]])}],['panel','Panel cách nhiệt 50 mm (λ = 0,035)','50 mm insulated panel (λ = 0.035)',{uroof:U(.14,[[.05,.035]])}]],
 lighting:[['l5','5 W/m²','5 W/m²',{lights:5}],['l8','8 W/m²','8 W/m²',{lights:8}],['l10','10 W/m²','10 W/m²',{lights:10}],['l15','15 W/m²','15 W/m²',{lights:15}],['l20','20 W/m²','20 W/m²',{lights:20}]],
 glass:[['single','Kính đơn trong · nhôm · mở quay','Clear single glazing · aluminium · hinged',{uglass:6.7,shgc:.57}],['tinted','Kính đơn màu · nhôm · mở quay','Tinted single glazing · aluminium · hinged',{uglass:6.6,shgc:.41}],['double','Kính đôi trong · nhôm · cố định/trượt','Clear double glazing · aluminium · fixed/sliding',{uglass:4.8,shgc:.59}],['lowe','Kính đôi Low-E · nhôm cách nhiệt · cố định/trượt','Low-E double glazing · thermal-break aluminium · fixed/sliding',{uglass:3.1,shgc:.27}]]
};
function values(kind,row,psy){if(kind!=='city')return row[3];const p=round(pressure(row[5]),3);return {tout:row[3],rhout:round(psy(row[3],'wb',row[4],p*1000).rh,1),pressure:p};}
if(typeof module!=='undefined')module.exports={data,values,pressure,U};
if(typeof document==='undefined')return;
const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,labels={city:L('Thành phố / ngoài trời','City / outdoor conditions'),use:L('Loại không gian','Space type'),wall:L('Cấu tạo tường','Wall assembly'),roof:L('Cấu tạo mái','Roof assembly'),glass:L('Loại cửa kính','Window type'),lighting:L('Công suất chiếu sáng','Lighting power density')},get=id=>document.getElementById('c-'+id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString(en?'en-US':'vi-VN',{maximumFractionDigits:3});
data.city.sort((a,b)=>a[en?2:1].localeCompare(b[en?2:1],en?'en':'vi'));
const box=document.createElement('section');box.className='heat-presets';box.innerHTML='<button type="button" class="heat-preset-heading disclosure-button" id="c-preset-toggle" aria-expanded="true" aria-controls="c-preset-content"><h3>'+L('Chọn nhanh','Quick presets')+'</h3><span class="disclosure-state"><span data-disclosure-label>'+L('Ẩn','Hide')+'</span><span class="disclosure-chevron" aria-hidden="true">⌄</span></span></button><div id="c-preset-content"><p class="field-help">'+L('Mẫu tham khảo cho tính sơ bộ; vẫn sửa được từng ô. Loại không gian chỉ điền nhiệt mỗi người và chiếu sáng; tự nhập số người, thiết bị và gió tươi.','Reference presets for preliminary sizing; every input remains editable. Space type fills occupant gains and lighting only; enter occupancy, equipment and outdoor airflow.')+'</p><div class="heat-preset-grid">'+Object.keys(data).map(k=>'<div><label for="c-preset-'+k+'">'+labels[k]+'</label><select id="c-preset-'+k+'"><option value="">'+L('Tùy chỉnh / chưa chọn','Custom / not selected')+'</option>'+data[k].map(r=>'<option value="'+r[0]+'">'+esc(r[en?2:1])+'</option>').join('')+'</select></div>').join('')+'</div><div class="heat-preset-status" aria-live="polite"></div><details class="heat-preset-reference"><summary>'+L('Xem bảng giá trị & nguồn tham khảo','View reference values & sources')+'</summary><div class="heat-preset-tables"></div></details></div>';
document.querySelector('.heat-visual').before(box);
function presetDisclosure(open){get('preset-content').hidden=!open;get('preset-toggle').setAttribute('aria-expanded',String(open));get('preset-toggle').querySelector('[data-disclosure-label]').textContent=open?L('Ẩn','Hide'):L('Hiện','Show');}presetDisclosure(!window.matchMedia('(max-width:700px)').matches);get('preset-toggle').addEventListener('click',()=>presetDisclosure(get('preset-content').hidden));
const note=L('Tường/mái là cấu tạo mẫu: U = 1/(R trong + Σ d/λ + R ngoài). Giả định λ (W/mK): gạch 0,77; trát 0,72; bê tông 2,5; cách nhiệt 0,035. R bề mặt: tường 0,17; mái 0,14 m²K/W. Chưa xét cầu nhiệt. Cửa kính là giá trị toàn bộ cửa gồm khung, lớp khí trong kính đôi. Ưu tiên dữ liệu nhà sản xuất.','Walls/roofs are example assemblies: U = 1/(inside R + Σ d/λ + outside R). Assumed λ (W/mK): brick 0.77; plaster 0.72; concrete 2.5; insulation 0.035. Surface R: walls 0.17; roofs 0.14 m²K/W. Thermal bridges are excluded. Window values include frames; double glazing is air-filled. Prefer manufacturer data.');
const scope=L('Thành phố: điều kiện làm lạnh 1% ASHRAE 2021; độ ẩm suy từ nhiệt độ khô và ướt đi kèm, áp suất ước tính theo cao độ trạm. Không phải thời tiết hiện tại hay điều kiện cực đại khử ẩm. Loại không gian: nhiệt mỗi người tại khoảng 24°C; chiếu sáng là giả định khởi đầu. Các mức chiếu sáng chỉ để chọn nhanh, không phải yêu cầu tiêu chuẩn; ưu tiên tổng công suất đèn thực tế chia diện tích sàn. Tự nhập số người, thiết bị và gió tươi theo thực tế. Nhiệt người tại nhà hàng đã gồm phần thức ăn theo bảng tham khảo, chưa gồm bếp; nhà máy chưa gồm nhiệt quá trình.','Cities: ASHRAE 2021 1% cooling conditions; RH derived from paired dry/wet-bulb temperatures, pressure estimated from station elevation. These are neither current weather nor peak dehumidification conditions. Space types: occupant gains at approximately 24°C; lighting is a starting assumption. Lighting levels are shortcuts, not code requirements; prefer actual installed lighting watts divided by floor area. Enter actual occupancy, equipment and outdoor airflow. Restaurant occupant gains include the table’s food allowance, but exclude kitchen loads; factory excludes process heat.');
const sources='<p class="field-help">'+L('Nguồn: ','Sources: ')+'<a href="https://xp20.ashrae.org/SupplementalFiles/PHVAC9/Design_Conditions_for_Selected_Locations-SI.pdf" target="_blank" rel="noopener noreferrer nofollow">ASHRAE 2021 · '+L('khí hậu','climate')+'</a> · <a href="https://handbook.ashrae.org/Handbooks/F21/SI/f21_ch18/f21_ch18_si.aspx" target="_blank" rel="noopener noreferrer nofollow">ASHRAE · '+L('nhiệt do người','occupant gains')+'</a> · <a href="https://www.planningportal.nsw.gov.au/basix-thermal-comfort/diy-method/windows/frame-glass-types/default-window-data" target="_blank" rel="noopener noreferrer nofollow">NSW BASIX · '+L('cửa kính','windows')+'</a> · <a href="https://www.nist.gov/publications/letter-circular-190altitude-pressure-tables-based-united-states-standard-atmosphere" target="_blank" rel="noopener noreferrer nofollow">'+L('Khí quyển tiêu chuẩn','Standard atmosphere')+'</a></p>';
function description(k,r,reference=false){const v=values(k,r,psyState);if(k==='city')return fmt(v.tout)+' °C · '+fmt(v.rhout)+'% RH · '+fmt(v.pressure)+' kPa ('+L('nhiệt độ bầu ướt','wet bulb')+' '+fmt(r[4])+' °C; '+L('cao độ','elevation')+' '+r[5]+' m)';if(k==='lighting')return fmt(v.lights)+' W/m²';if(k==='use')return L('Hiện / ẩn: ','Sensible / latent: ')+v.persons+' / '+v.personl+' W/'+L('người','person')+(reference?' · '+L('đèn khởi đầu','initial lighting')+' '+v.lights+' W/m²':'');return 'U = '+fmt(v.uwall??v.uroof??v.uglass)+' W/m²K'+(k==='glass'?' · SHGC = '+fmt(v.shgc):'');}
box.querySelector('.heat-preset-tables').innerHTML='<p class="field-help">'+scope+'</p>'+Object.keys(data).map(k=>'<h4>'+labels[k]+'</h4><div class="heat-preset-table-scroll"><table><thead><tr><th>'+L('Lựa chọn','Preset')+'</th><th>'+L('Giá trị áp dụng','Applied values')+'</th></tr></thead><tbody>'+data[k].map(r=>'<tr><td>'+esc(r[en?2:1])+'</td><td>'+description(k,r,true)+'</td></tr>').join('')+'</tbody></table></div>').join('')+'<p class="field-help">'+note+'</p>'+sources;
const current=k=>data[k].find(r=>r[0]===get('preset-'+k).value);
function matches(k,r){return Object.entries(values(k,r,psyState)).filter(([id])=>k!=='use'||id!=='lights').every(([id,v])=>get(id).value.trim()!==''&&Math.abs(+get(id).value-v)<1e-6);}
function selected(){return Object.keys(data).flatMap(k=>{const r=current(k);return r&&matches(k,r)?[[k,r]]:[];});}
function report(){const rows=selected();return rows.length?'<section class="report-section heat-preset-summary"><h3>'+L('Mẫu tham khảo đã áp dụng','Applied reference presets')+'</h3><table><tbody>'+rows.map(([k,r])=>'<tr><td>'+labels[k]+'</td><td>'+esc(r[en?2:1])+'<br>'+description(k,r)+'</td></tr>').join('')+'</tbody></table><p class="field-help">'+scope+'</p><p class="field-help">'+note+'</p>'+sources+'</section>':'';}
function refresh(){for(const k of Object.keys(data)){const r=current(k);if(r&&!matches(k,r))get('preset-'+k).value='';}box.querySelector('.heat-preset-status').innerHTML=selected().map(([k,r])=>'<p><b>'+labels[k]+':</b> '+description(k,r)+'</p>').join('');document.querySelector('.heat-results .heat-preset-summary')?.remove();const html=report();if(html)document.querySelector('.heat-results').insertAdjacentHTML('beforeend',html);}
box.addEventListener('change',e=>{const k=e.target.id.replace('c-preset-','');if(!data[k])return;const r=current(k);if(r)for(const [id,v] of Object.entries(values(k,r,psyState)))get(id).value=v;if(k==='use'&&r)get('preset-lighting').value=data.lighting.find(row=>row[3].lights===r[3].lights)?.[0]||'';coolingUpdate();refresh();get('area').dispatchEvent(new Event('input',{bubbles:true}));});
for(const input of heatInputs)input.addEventListener('input',refresh);
get('reset').addEventListener('click',()=>{Object.keys(data).forEach(k=>get('preset-'+k).value='');refresh();});
document.addEventListener('hvac-project-restore',refresh);
window.HVACHeatPresets={report};refresh();
})();
